<div class="report overflow-hidden rounded-xl border border-slate-300 bg-white shadow-sm"><div class="flex items-center justify-end gap-2 border-b bg-slate-50 p-3"><h1 class="mr-auto text-xl font-bold">Visit Report</h1><form method="GET" action="{{ route('warehouse.daily-visits.report') }}" class="flex flex-wrap items-center gap-2 text-sm"><span>From</span><input type="date" name="visit_date_from" value="{{ $fromDate }}" required class="h-9 border px-2"><span>To</span><input type="date" name="visit_date_to" value="{{ $toDate }}" required class="h-9 border px-2"><button class="h-9 bg-sky-500 px-4 text-white">Filter</button><button type="button" onclick="window.print()" class="h-9 border px-3">Print / PDF</button></form></div>@if($fromDate&&$toDate)<div class="p-5"><div class="text-center"><h2 class="text-lg font-bold">Visit Report</h2><p><b>Date:</b> {{ \Carbon\Carbon::parse($fromDate)->format('d M Y') }} to {{ \Carbon\Carbon::parse($toDate)->format('d M Y') }}</p><p><b>Total Beneficiaries:</b> {{ $visits->pluck('app_customer_id')->unique()->count() }} | <b>Working Days:</b> {{ $workingDays }}</p></div><div class="mt-4 grid gap-3 border bg-slate-50 p-3 text-xs md:grid-cols-3"><div><b>Area Name:</b> {{ $salesman->warehouse?->name ?: '-' }}<br><b>LSP:</b> {{ $salesman->name }}</div><div><b>Group Number:</b> {{ $visits->pluck('appCustomer.group_number')->filter()->unique()->implode(', ') ?: '-' }}</div><div><b>C.F:</b> {{$visitTypeCounts['C.F']??0}} &nbsp;<b>Re.V:</b> {{$visitTypeCounts['Re.V']??0}} &nbsp;<b>N.V:</b> {{$visitTypeCounts['N.V']??0}} &nbsp;<b>Reg.v:</b> {{$visitTypeCounts['Reg.v']??0}} &nbsp;<b>A.s:</b> {{$visitTypeCounts['A.s']??0}}</div></div><div class="mt-4 overflow-x-auto"><table class="min-w-full text-left text-xs"><thead><tr><th>SL</th><th>Visit Nature</th><th>Beneficiary Name</th><th>Beneficiary Cell No.</th><th>Group Number</th><th>Beneficiary Number</th><th>Date</th><th>Memo/Invoice No(s)</th><th>File</th><th>Total Amount</th><th>Fee Types (itemized)</th></tr></thead><tbody>@forelse($visits as $visit)<tr class="odd:bg-slate-50"><td>{{$loop->iteration}}</td><td>{{$visit->visit_type?:'-'}}</td><td>{{$visit->appCustomer?->name?:'-'}}</td><td>{{$visit->appCustomer?->mobile?:($visit->customer_number?:'No Number')}}</td><td>{{$visit->appCustomer?->group_number?:'N/A'}}</td><td>{{$visit->beneficiary_number?:'N/A'}}</td><td>{{$visit->visit_date?->format('Y-m-d').' '.($visit->created_at?->format('h:i A') ?? '')}}</td><td>{{is_array($visit->memo_no)?implode(', ',$visit->memo_no):($visit->memo_no?:'--')}}</td><td>@if($visit->attachment_path)<a href="{{ asset(str_starts_with($visit->attachment_path, 'uploads/') ? $visit->attachment_path : 'storage/' . $visit->attachment_path) }}" target="_blank" rel="noopener" title="Open attachment" aria-label="Open attachment" class="inline-flex h-8 w-8 items-center justify-center rounded bg-sky-500 text-white"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path stroke-linecap="round" stroke-linejoin="round" d="M6 3.75h8.25L18 7.5v12.75H6V3.75Z"/><path stroke-linecap="round" stroke-linejoin="round" d="M14 3.75V8h4M9 12h6M9 15h6"/></svg></a>@else<span class="text-slate-400">N/A</span>@endif</td><td>{{number_format($visit->fees->sum('amount'),0)}} BDT</td><td>@if($visit->fees->isNotEmpty())<ul class="m-0 list-disc pl-4">@foreach($visit->fees as $fee)<li>{{$fee->fee_type}}: {{$fee->amount}}</li>@endforeach</ul>@else<span class="text-slate-400">No fees</span>@endif</td></tr>@empty<tr><td colspan="11" class="p-8 text-center">No visits found.</td></tr>@endforelse</tbody></table></div><h3 class="mt-5 text-center text-sm font-bold">Summary</h3><table class="summary-table mt-1 min-w-full text-left text-xs"><thead><tr><th>Fee Type</th><th>Daily Target</th><th>Total Target</th><th>Achieve Amount</th><th>Achievement %</th></tr></thead><tbody>@php($targets=['Deworming'=>400,'Fattening'=>900,'Medicine'=>1200,'Treatment and others'=>300])@foreach($tar