<script>document.addEventListener('DOMContentLoaded',function(){var details=document.querySelector('.report > div:nth-of-type(2) > div.mt-4.grid');if(!details||details.children.length<3)return;var first=details.children[0],group=details.children[1],lsp=first.querySelectorAll('b')[1],lspName=lsp&&lsp.nextSibling?lsp.nextSibling.textContent.trim():'';if(lsp){lsp.nextSibling.remove();lsp.remove();var br=first.querySelector('br');if(br)br.remove()}group.innerHTML='<b>Group Number:</b> '+lspName;});</script>
